<?php include "../auth/cek_login.php";include "../koneksi.php";$q=mysqli_query($conn,"SELECT t.*,p.nama nama_pelanggan FROM transaksi t JOIN pelanggan p ON t.id_pelanggan=p.id ORDER BY t.id DESC");?><!doctype html><html><head><title>Transaksi</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content"><h1>Transaksi Penyewaan</h1><a class="btn" href="tambah.php">+ Transaksi Baru</a><a class="btn" href="../dashboard.php">Dashboard</a><table><tr><th>No</th><th>Kode</th><th>Pelanggan</th><th>Tgl Sewa</th><th>Kembali</th><th>Total</th><th>Status</th><th>Aksi</th></tr><?php $n=1;while($d=mysqli_fetch_assoc($q)):?><tr><td><?=$n++?></td><td><?=$d['kode_transaksi']?></td><td><?=$d['nama_pelanggan']?></td><td><?=$d['tanggal_sewa']?></td><td><?=$d['tanggal_rencana_kembali']?></td><td>Rp <?=number_format($d['total_harga'],0,',','.')?></td><td><?=$d['status']?></td><td><a href="detail.php?id=<?=$d['id']?>">Detail</a> <?php if($d['status']=='Disewa'):?>| <a href="../pengembalian/proses.php?id=<?=$d['id']?>">Kembalikan</a><?php endif;?> | <a href="hapus.php?id=<?=$d['id']?>" onclick="return confirm('Hapus?')">Hapus</a></td></tr><?php endwhile;?></table></div></body></html>